<script>
import { saveExcel } from '@progress/kendo-vue-excel-export'

// 匯出Excel的資料預設
// const ListModelExport = {
//   count: 0,
//   rows: [{}]
// }

export default {
  data () {
    return {
      // 匯出Excel資料用
      items: [],
      exportColumns: [
        { field: 'date', title: '日期' },
        { field: 'name', title: '名子' },
        { field: 'location', title: '地址' }
      ],
      exportData: '',
      startTime: '',
      endTime: '',
      account: '',
      tempArray: [],
      tempdef: {
        DTSTART: '',
        SUMMARY: '',
        LOCATION: ''
      }
    }
  },
  created () {
    // console.log(this.spliceHanhle())
  },
  methods: {
    async handleExport () {
      const xhr = new XMLHttpRequest()
      const url = 'https://clients6.google.com/calendar/v3/calendars/' + this.account + '/events?eventTypes=default&eventTypes=focusTime&eventTypes=outOfOffice&singleEvents=true&timeZone=Asia/Taipei&calendarId=' + this.account + '&maxResults=999&timeMin=' + this.startTime + 'T00:00:00.000Z&timeMax=' + this.endTime + 'T00:00:00.000Z&key=AIzaSyBix6csrL3Z5CX-HAQHBniqu_GznaICxJI&orderBy=startTime'

      xhr.open('GET', url)
      // xhr.open('GET', 'https://clients6.google.com/calendar/v3/calendars/yangfan.tec.13%40gmail.com/events?eventTypes=default&eventTypes=focusTime&eventTypes=outOfOffice&singleEvents=true&timeZone=Asia%2FTaipei&calendarId=yangfan.tec.13%40gmail.com&maxResults=999&timeMin=2025-04-01T00%3A00%3A00.000%2B08%3A00&timeMax=2025-08-20T00%3A00%3A00.000%2B08%3A00&key=AIzaSyBNlYH01_9Hc5S1J9vuFmu2nUqBZJNAXxs&orderBy=startTime')

      xhr.responseType = 'json'

      xhr.send()

      // the response is {"message": "Hello, world!"}
      xhr.onload = () => {
        const responseObj = xhr.response
        console.log(responseObj)
        console.log(responseObj.items)
        this.exportData = responseObj.items
        for (let i = 0; i < this.exportData.length; i++) {
          this.exportData[i].time = this.dateFormat(new Date(this.exportData[i].start.dateTime).getTime())
        }
        console.log(responseObj.items)

        this.items = this.createRandomData(this.exportData.length)
        // 導出Excel
        saveExcel({
          data: this.items,
          fileName: '日曆',
          columns: this.exportColumns
        })
      }
    },
    async handleExportII () {
      this.items = this.createRandomData(this.tempArray.length)
      // 導出Excel
      saveExcel({
        data: this.items,
        fileName: '日曆',
        columns: this.exportColumns
      })
    },
    createRandomData (count) {
      return Array(count)
        .fill({}).map((_, idx) => ({
          date: this.tempArray[idx].DTSTART,
          name: this.tempArray[idx].SUMMARY,
          location: this.tempArray[idx].LOCATION
        }))
    },
    dateFormat (date) {
      const objectDate = new Date(date)
      const day = objectDate.getDate() < 10 ? '0' + objectDate.getDate() : objectDate.getDate()
      const month = objectDate.getMonth() + 1 < 10 ? '0' + (objectDate.getMonth() + 1) : objectDate.getMonth() + 1
      const year = objectDate.getFullYear()
      // const h = objectDate.getHours() < 10 ? '0' + objectDate.getHours() : objectDate.getHours()
      // const m = objectDate.getMinutes() < 10 ? '0' + objectDate.getMinutes() : objectDate.getMinutes()
      // const s = objectDate.getSeconds() < 10 ? '0' + objectDate.getSeconds() : objectDate.getSeconds()
      return year + '-' + month + '-' + day
    },
    handleFiles (element) {
      const file = element.target.files[0]
      const reader = new FileReader()
      reader.readAsText(file)
      reader.onload = () => {
        this.convert(reader.result.split('\n'))
      }
    },
    convert (str) {
      console.log('str')
      console.log(str)
      console.log(str.length)

      // let _keywordIndex = 0
      // let tempArray = []
      this.tempArray = []
      // this.tempdef = {
      //   DTSTART: '',
      //   DTEND: '',
      //   SUMMARY: '',
      //   LOCATION: ''
      // }

      let ddd = false

      console.log(this.tempdef.DTSTART)
      for (let i = 0; i < str.length; i++) {
        console.log(str[i])
        console.log(str[i] === 'BEGIN:VEVENT\r')

        if (str[i] === 'BEGIN:VEVENT\r') {
          ddd = true
        }
        console.log(str[i] === 'END:VEVENT\r')
        if (str[i] === 'END:VEVENT\r') {
          ddd = false
          console.log(this.tempdef.SUMMARY)

          this.tempArray.push(JSON.parse(JSON.stringify(this.tempdef)))
          console.log(this.tempArray)
        }

        console.log(ddd)
        if (ddd === true) {
          console.log('45678978')
          for (let j = 0; j < Object.keys(this.tempdef).length; j++) {
            console.log(Object.keys(this.tempdef)[j])
            if (str[i].match('^' + Object.keys(this.tempdef)[j])) {
              const eeee = Object.keys(this.tempdef)[j]
              console.log(this.tempdef[0])
              console.log(eeee)
              console.log(eeee.length)
              console.log(str[i].substring(eeee.length + 1))
              console.log(this.tempdef[eeee])
              this.tempdef[eeee] = str[i].substring(eeee.length + 1, str[i].length - 1)
            }
          }
        }
        console.log(Object.keys(this.tempdef))

        // if (input[i].match('^' + KEY_WORDS.WORDS[_keywordIndex])) {
        //   console.log(input[i].match('^' + KEY_WORDS.WORDS[_keywordIndex]) == KEY_WORDS.WORDS[_keywordIndex])

        //   tempArray[_keywordIndex] = input[i].substring(KEY_WORDS.SUBSTRING[_keywordIndex]);
        //   console.log(input[i])
        //   console.log(tempArray)
        //   _keywordIndex++;

        //   console.log(_keywordIndex)
        //   if (_keywordIndex === KEY_WORDS.WORDS.length) {
        //     handleEventRecord(tempArray);
        //     _keywordIndex = 0;
        //     tempArray = [];
        //   }
        // }
      }
      for (let i = 0; i < this.tempArray.length; i++) {
        // console.log(this.spliceHanhle(this.tempArray[i].DTSTART.substring(0, 8)))
        this.tempArray[i].DTSTART = this.spliceHanhle(this.tempArray[i].DTSTART.substring(0, 8))
      }
    },
    spliceHanhle (v) {
      let str = v
      const indexes = [4, 6]
      const newStr = '-'

      indexes.sort(function (a, b) {
        return b - a
      })

      indexes.forEach((index) => {
        str = str.slice(0, index) + newStr + str.slice(index)
      })
      return str
      // console.log('str')
      // console.log(str)
    }
  }
}
</script>

